const{test}=require('node:test'),assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs'),path=require('node:path');
function deferred(){let resolve;const promise=new Promise(r=>resolve=r);return{promise,resolve};}
function fixture(adapters){let stopped=0,closed=0,disposed=0,states=[],frames=[];const video={readyState:0,videoWidth:640,videoHeight:360,play:async()=>{},pause(){},srcObject:null},track={stop(){stopped++;}},stream={getTracks:()=>[track]},model={detect:async()=>[],dispose(){disposed++;}},hand={setOptions(){},onResults(){},send:async()=>{},close(){closed++;}},ctx={window:{},navigator:{mediaDevices:{getUserMedia:async()=>stream}},document:{createElement:()=>({getContext:()=>({drawImage(){}})}),hidden:false},performance,Promise,Error,setTimeout,clearTimeout};vm.createContext(ctx);vm.runInContext(fs.readFileSync(path.join(__dirname,'../experience/camera-physics/vision.js'),'utf8'),ctx);const session=ctx.CameraPhysicsVision.createSession(video,{state:(s)=>states.push(s),frame:f=>frames.push(f)},{camera:async()=>stream,load:async()=>({detector:model,hand}),...adapters});return{session,video,stream,model,hand,states,frames,counts:()=>({stopped,closed,disposed})};}
test('Camera permission resolving after Stop is immediately released',async()=>{const d=deferred(),f=fixture({camera:()=>d.promise});const task=f.session.start();f.session.stop();d.resolve(f.stream);await task;assert.equal(f.counts().stopped,1);assert.equal(f.video.srcObject,null);assert.ok(!f.states.includes('running'));});
test('Late model completion is disposed instead of restarting camera analysis',async()=>{const d=deferred(),f=fixture({load:()=>d.promise});const task=f.session.start();await new Promise(r=>setImmediate(r));f.session.stop();d.resolve({detector:f.model,hand:f.hand});await task;assert.deepEqual(f.counts(),{stopped:1,closed:1,disposed:1});assert.ok(!f.states.includes('running'));});
test('Stopping during hand inference suppresses late detections and closes both models',async()=>{const d=deferred(),f=fixture();f.hand.send=()=>d.promise;f.video.readyState=2;await f.session.start();f.session.stop();d.resolve();await new Promise(r=>setImmediate(r));assert.equal(f.frames.length,0);assert.deepEqual(f.counts(),{stopped:1,closed:1,disposed:1});});
test('Stopping during object inference discards its late result',async()=>{const d=deferred(),f=fixture();f.model.detect=()=>d.promise;f.video.readyState=2;await f.session.start();await new Promise(r=>setImmediate(r));f.session.stop();d.resolve([{class:'book',score:.99,bbox:[100,100,100,100]}]);await new Promise(r=>setImmediate(r));assert.equal(f.frames.length,0);assert.deepEqual(f.counts(),{stopped:1,closed:1,disposed:1});});
test('Repeated starts never open concurrent camera requests',async()=>{let calls=0;const d=deferred(),f=fixture({camera:()=>{calls++;return d.promise;}});const a=f.session.start(),b=f.session.start();assert.equal(calls,1);f.session.stop();d.resolve(f.stream);await Promise.all([a,b]);});
test('Model failure releases camera and leaves a retryable stopped session',async()=>{const f=fixture({load:async()=>{throw Error('offline');}});await f.session.start();assert.equal(f.session.isActive(),false);assert.equal(f.counts().stopped,1);assert.equal(f.states.at(-1),'error');assert.equal(f.video.srcObject,null);});
test('Detection age starts at capture, never at delayed model completion',async()=>{const d=deferred(),f=fixture();let captureBound;f.hand.send=async()=>{captureBound=performance.now();};f.model.detect=()=>d.promise;f.video.readyState=2;await f.session.start();await new Promise(r=>setImmediate(r));d.resolve([]);await new Promise(r=>setImmediate(r));f.session.stop();assert.equal(f.frames.length,1);assert.ok(f.frames[0].time<=captureBound);assert.ok(f.frames[0].latency>=0);});
